const inputJson = $json || {};
let body = inputJson.body || {};
const isAgent = (inputJson.sessionId && inputJson.intent) || (body.sessionId && body.intent) || inputJson._isAgent || body._isAgent;
const headers = { ...(inputJson.headers || {}) };
let method = inputJson.method || headers['x-forwarded-method'] || 'POST';

if (isAgent) {
  body = { ...inputJson, ...body };
  body.ApiCode = body.intent || inputJson.intent;
  body.params = { ...inputJson, ...(body.params || {}) };
  method = 'POST';
  if (inputJson.authorization || body.authorization) headers.authorization = inputJson.authorization || body.authorization;
  if (inputJson.cookie || body.cookie) headers.cookie = inputJson.cookie || body.cookie;
}

if (!headers.authorization && headers.cookie) {
  const match = String(headers.cookie).match(/(?:^|;\s*)auth_token=([^;]+)/);
  if (match) headers.authorization = 'Bearer ' + match[1];
}

let apiCode = body.ApiCode || body.StoredProcedure || '';
if (!/^@[a-zA-Z0-9_]+$/.test(apiCode)) apiCode = '@invalid_code';

const params = { ...(body.params || {}) };
delete params['@Username'];
delete params.Username;
delete params.username;

const sqlBlacklist = /(\bDROP\s+TABLE\b|\bTRUNCATE\s+TABLE\b|\bUNION\s+SELECT\b)/i;
for (const key of Object.keys(params)) {
  const value = String(params[key]);
  if (sqlBlacklist.test(value)) {
    apiCode = '@invalid_code';
    params['@SecurityBlock'] = 'Blocked suspicious SQL input';
  }
}

const requestOrigin = String(headers.origin || headers.Origin || '').replace(/\/$/, '');
const allowedOrigins = new Set(["http://localhost:3000","http://127.0.0.1:3000","https://medtest.bms79.com"]);
const corsOrigin = allowedOrigins.has(requestOrigin) ? requestOrigin : 'https://cors.invalid';
return [{ json: {
  ...inputJson,
  _isAgent: Boolean(isAgent),
  headers,
  body: { ...body, ApiCode: apiCode, params },
  _method: String(method).toUpperCase(),
  _corsOrigin: corsOrigin,
  _corsOrigin: corsOrigin
} }];

const execNode = $('Enforce API Capability').first().json;
const apiCode = execNode.body.ApiCode || '@invalid_code';
const realUsername = String(execNode.verifiedIdentity?.internalUserId || '');
if (!realUsername) throw new Error('AUTHORIZATION_REQUIRED');
let paramsStr = execNode._paramsSafeStr || '{}';

const query = `
DECLARE @ApiCode VARCHAR(100) = '${apiCode}';
DECLARE @ParamsJSON NVARCHAR(MAX) = N'${paramsStr}';

-- GLOBAL SMART CUSTOMER RESOLUTION (NAME TO ID)
DECLARE @MaKhachHang NVARCHAR(100) = '';
IF ISJSON(@ParamsJSON) = 1
BEGIN
    SELECT @MaKhachHang = [value] FROM OPENJSON(@ParamsJSON) WHERE [key] IN ('@MaKhachHang', '@ObjectID');
END

IF @MaKhachHang <> '' AND NOT EXISTS (SELECT 1 FROM dbo.CF_ObjectTbl WHERE ObjectID = @MaKhachHang)
BEGIN
    DECLARE @Username VARCHAR(100) = '';
    IF ISJSON(@ParamsJSON) = 1
    BEGIN
        SELECT @Username = [value] FROM OPENJSON(@ParamsJSON) WHERE [key] = '@Username';
    END

    DECLARE @ResolvedID VARCHAR(50) = ''
    DECLARE @CleanSearch NVARCHAR(100) = dbo.ufn_clean_customer_name(@MaKhachHang)

    SELECT TOP 1 @ResolvedID = ObjectID 
    FROM dbo.CF_ObjectTbl 
    WHERE (dbo.ufn_clean_customer_name(ObjectName) LIKE '%' + @CleanSearch + '%'
       OR ObjectID LIKE '%' + @CleanSearch + '%')
       AND (@Username = '' OR ObjectID IN (SELECT ObjectID FROM dbo.AR_GetObjectByUserFnc(@Username)))
    ORDER BY 
        CASE WHEN ObjectID = @CleanSearch THEN 1
             WHEN dbo.ufn_clean_customer_name(ObjectName) = @CleanSearch THEN 2
             WHEN dbo.ufn_clean_customer_name(ObjectName) LIKE @CleanSearch + '%' THEN 3
             ELSE 4
        END,
        COALESCE((SELECT MAX(DocumentDate) FROM AR_InvoiceTbl WHERE ObjectID = CF_ObjectTbl.ObjectID), '1900-01-01') DESC,
        LEN(ObjectName) ASC;

    IF @ResolvedID <> ''
    BEGIN
        SET @ParamsJSON = JSON_MODIFY(@ParamsJSON, '$."@MaKhachHang"', @ResolvedID);
        SET @ParamsJSON = JSON_MODIFY(@ParamsJSON, '$."@ObjectID"', @ResolvedID);
    END
END

IF @ApiCode = '@lap_don_hang'
BEGIN
    DECLARE @CartMaKH NVARCHAR(100) = '';
    DECLARE @ItemList NVARCHAR(MAX) = '[]';
    IF ISJSON(@ParamsJSON) = 1
    BEGIN
        SELECT @CartMaKH = [value] FROM OPENJSON(@ParamsJSON) WHERE [key] IN ('@MaKhachHang', '@ObjectID');
        SELECT @ItemList = [value] FROM OPENJSON(@ParamsJSON) WHERE [key] = '@ItemList';
    END

    SELECT 
        0 AS [code], 
        N'Dạ, em đang chuẩn bị giỏ hàng lên đơn cho khách hàng. Sếp kiểm tra lại thông tin trong bảng nhé!' AS [msg],
        'CART' AS [Metadata_UiTemplate],
        @CartMaKH AS [MaKhachHang],
        @ItemList AS [ItemList];
    RETURN;
END

DECLARE @SPName NVARCHAR(MAX);
DECLARE @UiTemplate VARCHAR(50) = 'DEFAULT';

SELECT @SPName = StoredProcedure, @UiTemplate = ISNULL(UiTemplate, 'DEFAULT') FROM dbo.API_Definition WHERE ApiCode = @ApiCode AND IsActive = 1;

IF @SPName IS NULL
BEGIN
    SELECT 2 AS code, 'Missing para or Object not support' AS msg, 'DEFAULT' AS uiTemplate FOR JSON PATH;
    RETURN;
END

SELECT @UiTemplate AS Metadata_UiTemplate; -- Meta set

DECLARE @SQL NVARCHAR(MAX) = N'EXEC ' + QUOTENAME(@SPName) + N' ';

IF @ParamsJSON IS NOT NULL AND @ParamsJSON != '' AND @ParamsJSON != '{}'
BEGIN
    SELECT @SQL = @SQL + [key] + 
        CASE WHEN [type] = 0 THEN ' = NULL, '
             ELSE N' = N''' + REPLACE(CAST([value] AS NVARCHAR(MAX)), '''', '''''') + N''', ' END
    FROM OPENJSON(@ParamsJSON)
    WHERE [key] LIKE '@%'
      AND [key] COLLATE DATABASE_DEFAULT IN (SELECT name COLLATE DATABASE_DEFAULT FROM sys.parameters WHERE object_id = OBJECT_ID(@SPName));

    IF RIGHT(@SQL, 2) = ', ' SET @SQL = LEFT(@SQL, LEN(@SQL) - 1);
END

EXEC sp_executesql @SQL;
`.trim();

return [{ json: { query } }];

const items = $input.all();
let uiTemplate = 'DEFAULT';

if (!items || items.length === 0) {
  return [{ json: { reply: 'Khong tim thay du lieu', status: 'success', count: 0, data: [], uiTemplate: uiTemplate } }];
}

const JSON_KEY = 'JSON_F52E2B61-18A1-11d1-B105-00805F49916B';
let payload = items.map(i => i.json);
// --- UPDATE ENCODING: DECODE UTF-8 FROM LATIN1/WINDOWS-1252 ---
function decodeUtf8(str) {
  if (typeof str !== 'string') return str;
  try {
    return decodeURIComponent(escape(str));
  } catch (e) {
    return str;
  }
}
function cleanRow(obj) {
  if (!obj || typeof obj !== 'object') return obj;
  const newObj = {};
  for (const [k, v] of Object.entries(obj)) {
    if (typeof v === 'string') {
      newObj[k] = decodeUtf8(v);
    } else if (Array.isArray(v)) {
      newObj[k] = v.map(cleanRow);
    } else if (typeof v === 'object' && v !== null) {
      newObj[k] = cleanRow(v);
    } else {
      newObj[k] = v;
    }
  }
  return newObj;
}
payload = payload.map(cleanRow);


// 0. Extract Metadata
const metaIdx = payload.findIndex(r => r.Metadata_UiTemplate !== undefined);
if (metaIdx !== -1) {
  uiTemplate = payload[metaIdx].Metadata_UiTemplate;
  if (uiTemplate === 'CART') {
    payload[metaIdx] = { 
      success: true, 
      MaKhachHang: payload[metaIdx].MaKhachHang,
      ItemList: payload[metaIdx].ItemList
    };
  } else {
    payload.splice(metaIdx, 1);
  }
}

// Preserve business and permission errors returned by stored procedures.
const businessError = payload.find(row => {
  if (!row || typeof row !== 'object') return false;
  const message = row.Msg !== undefined ? row.Msg : row.msg;
  const messageType = Number(row.MsgType !== undefined ? row.MsgType : row.msgType);
  return message && messageType >= 1;
});
if (businessError) {
  return [{ json: {
    reply: businessError.Msg || businessError.msg,
    status: 'error',
    code: Number(businessError.MsgType || businessError.msgType || 1),
    count: 0,
    data: [],
    uiTemplate
  } }];
}

// Xu ly SQL FOR JSON PATH output (khi SP khong tim thay trong API_Definition)
// N8N MS SQL tra ve [{JSON_F52E...: '[{"code":2,"msg":"..."}]'}]
if (payload.length === 1 && payload[0][JSON_KEY] !== undefined) {
  try {
    const inner = JSON.parse(payload[0][JSON_KEY]);
    if (Array.isArray(inner) && inner.length > 0) {
      if (inner[0].code === 1 || inner[0].code === 2) {
        return [{ json: { reply: inner[0].msg || 'ApiCode chua duoc dang ky trong he thong', status: 'error', data: [], uiTemplate: uiTemplate } }];
      }
      payload = inner;
    }
  } catch(e) {
    return [{ json: { reply: 'Loi xu ly ket qua SQL', status: 'error', data: [], uiTemplate: uiTemplate } }];
  }
  if (payload.length === 1 && payload[0][JSON_KEY] !== undefined) {
    return [{ json: { reply: 'Khong tim thay API phu hop', status: 'error', data: [], uiTemplate: uiTemplate } }];
  }
}

// Kiem tra loi don gian {code, msg}
if (payload.length === 1 && (payload[0].code === 1 || payload[0].code === 2 || payload[0].error)) {
  return [{ json: { reply: payload[0].msg || payload[0].error || 'Loi khong xac dinh', status: 'error', data: [], uiTemplate: uiTemplate } }];
}

// Loc bo cac row con JSON_KEY hoac object rong do n8n MS SQL alwaysOutputData: true tra ve
payload = payload.filter(r => {
  if (!r) return false;
  if (r[JSON_KEY] !== undefined) return false;
  const keys = Object.keys(r).filter(k => k !== 'JSON_KEY');
  return keys.length > 0;
});

if (payload.length === 0) {
  return [{ json: { reply: 'Khong tim thay du lieu', status: 'success', count: 0, data: [], uiTemplate: uiTemplate } }];
}

// --- DATA BYPASS Cá»¦A GIAI ÄOáº N 2 ---
let isAgent = false;
let sessionId = 'unknown';
try {
    const checkNode = $('Check Method Execute').first();
    if (checkNode && checkNode.json) {
        if (checkNode.json._isAgent) isAgent = true;
        if (checkNode.json.body && checkNode.json.body.sessionId) sessionId = checkNode.json.body.sessionId;
    }
} catch(e) {}

if (isAgent) {
    let cacheId = sessionId + '_' + Math.random().toString(36).substr(2, 9);
    try {
        const crypto = require('crypto');
        cacheId = crypto.createHmac('sha256', 'Medstand_Enterprise_Secret').update(sessionId + '_' + ($execution ? $execution.id : 'local')).digest('hex');
    } catch(e) { }

    const now = Date.now();
    const TTL_MS = 30 * 60 * 1000;

    // 1. StaticData (Workflow Local)
    try {
        const staticData = $getWorkflowStaticData('global');
        if (!staticData.dataCache) staticData.dataCache = {};
        for (const key in staticData.dataCache) {
            if (staticData.dataCache[key] && staticData.dataCache[key].timestamp && (now - staticData.dataCache[key].timestamp > TTL_MS)) {
                delete staticData.dataCache[key];
            }
        }
        staticData.dataCache[cacheId] = {
            timestamp: now,
            data: payload
        };
    } catch(e) {}

    // 2. Global Node.js Object (Cross-Workflow Memory)
    try {
        if (!global.__MEDSTAND_CACHE__) global.__MEDSTAND_CACHE__ = {};
        for (const key in global.__MEDSTAND_CACHE__) {
            if (global.__MEDSTAND_CACHE__[key] && global.__MEDSTAND_CACHE__[key].timestamp && (now - global.__MEDSTAND_CACHE__[key].timestamp > TTL_MS)) {
                delete global.__MEDSTAND_CACHE__[key];
            }
        }
        global.__MEDSTAND_CACHE__[cacheId] = {
            timestamp: now,
            data: payload
        };
    } catch(e) {}

    // 3. File System (Cross-Worker / Disk Backup)
    try {
        const fs = require('fs');
        const path = require('path');
        const os = require('os');
        const cacheDir = path.join(os.tmpdir(), 'n8n_cache');
        if (!fs.existsSync(cacheDir)) fs.mkdirSync(cacheDir, { recursive: true });
        fs.writeFileSync(path.join(cacheDir, cacheId + '.json'), JSON.stringify(payload));
    } catch(e) {}

    // TÃ­nh toÃ¡n TÃ³m táº¯t nhanh cho AI (Mini Summary)
    let tongTien = 0;
    for(const r of payload) {
        if(r.ThanhTien) tongTien += Number(r.ThanhTien);
        if(r.TongTien) tongTien += Number(r.TongTien);
        if(r.DoanhThu) tongTien += Number(r.DoanhThu);
    }

    let summary = `ÄÃ£ tÃ¬m tháº¥y ${payload.length} káº¿t quáº£.`;
    if(tongTien > 0) summary += ` Tá»•ng tiá»n táº¡m tÃ­nh: ${tongTien}.`;
    summary += ` MÃ£ NgÄƒn KÃ©o: ${cacheId}`;

    // CHá»ˆ TRáº¢ Vá»€ TÃ“M Táº®T CHO AI Äá»ŒC
    return [{ json: { status: 'success', Cache_ID: cacheId, summary: summary, count: payload.length, data: payload, uiTemplate: uiTemplate } }];
}
// ----------------------------------

return [{ json: { 
  reply: 'Tim thay ' + payload.length + ' ket qua.', 
  status: 'success', 
  count: payload.length, 
  data: payload, uiTemplate: uiTemplate 
} }];

const request = $('Check Method Execute').first().json;
const auth = $json.auth || {};
const verifiedIdentity = $json.verifiedIdentity;
if (!auth.ok || !verifiedIdentity?.internalUserId) throw new Error('AUTHORIZATION_REQUIRED');

const rawParams = { ...(request.body?.params || {}) };
const reservedScopeKeys = new Set([
  '@username', 'username', '@user', 'user',
  '@employeeid', 'employeeid', '@sysemployeeid', 'sysemployeeid',
  '@branchid', 'branchid', '@sysbranchid', 'sysbranchid',
  '@managerid', 'managerid', '@sysmanagerid', 'sysmanagerid',
  '@ceoid', 'ceoid', '@sysceoid', 'sysceoid'
]);
const params = {};
const ignoredScopeParams = [];
for (const [key, value] of Object.entries(rawParams)) {
  const normalized = String(key).toLowerCase();
  if (reservedScopeKeys.has(normalized) || normalized.startsWith('@sys')) {
    ignoredScopeParams.push(key);
    continue;
  }
  params[key] = value;
}

params['@Username'] = String(verifiedIdentity.internalUserId);
params['@User'] = String(verifiedIdentity.internalUserId);
if (verifiedIdentity.employeeId) params['@SYSEmployeeID'] = String(verifiedIdentity.employeeId);

return [{ json: {
  ...request,
  auth,
  verifiedIdentity,
  body: { ...request.body, params },
  _ignoredScopeParams: ignoredScopeParams,
  _paramsSafeStr: JSON.stringify(params).replace(/'/g, "''")
} }];

